'use strict';
(() => {
const D=window.EIA_DATA;
const $=s=>document.querySelector(s), content=$('#content');
if(!D){content.textContent='Не удалось загрузить данные. Сохраните index.html, app.js, style.css и site-data.js вместе.';return;}
const E=new Map(D.entities.map(x=>[x.id,x])), S=new Map(D.sources.map(x=>[x.id,x])), C=new Map(D.claims.map(x=>[x.id,x]));
const G=new Map(D.edges.map(x=>[x.id,x]));
const gradeNames={A:'Документировано',B:'Убедительное подтверждение',C:'Требует сверки',D:'Не подтверждено'};
const state={chain:null,step:99,sourcePage:0,sourceFilter:'used',sourceQuery:'',entityQuery:'',entityKind:'',entityCountry:'',catalogueQuery:'',graphGrade:'',graphPeriod:'',graphKind:'',graphCountry:'',graphNodeKind:'',path:null,alternatives:[]};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s??'').toLocaleLowerCase('ru').replace(/ё/g,'е');
const match=(text,q)=>norm(q).split(/\s+/).filter(Boolean).every(t=>norm(text).includes(t));
const safeURL=url=>/^https?:\/\//i.test(url)?esc(url):'#';
const money=v=>v===null?'Не установлено':new Intl.NumberFormat('ru-RU').format(v)+' ₽';
const shortName=id=>E.get(id)?.name.replace('Александр Леонидович Рабинович','Александр Рабинович').replace('Дмитрий Александрович Палагутин','Дмитрий Палагутин').replace('Екатерина Алексеевна Гребенскова','Екатерина Гребенскова')||id;
const badge=(grade,label)=>`<span class="badge ${esc(grade)}" title="${esc(gradeNames[grade]||'Статус')}">${esc(grade)} · ${esc(label||gradeNames[grade]||'')}</span>`;
const neutral=t=>`<span class="badge neutral">${esc(t)}</span>`;
const sources=ids=>`<div class="source-row">${[...new Set(ids)].map(id=>`<button class="citation" data-source="${esc(id)}" title="${esc(S.get(id)?.title||S.get(id)?.url||id)}">${esc(id)}</button>`).join('')}</div>`;
const objects=ids=>`<div class="chips">${[...new Set(ids)].map(id=>E.has(id)?`<a class="chip" href="#entity/${esc(id)}">${esc(shortName(id))}</a>`:'').join('')}</div>`;
const crumbs=(title,parent)=>`<div class="breadcrumb"><a href="#home">Исследование</a><span>/</span>${parent?`<a href="#${parent[0]}">${esc(parent[1])}</a><span>/</span>`:''}${esc(title)}</div>`;
function head(title,description,eyebrow='ОТКРЫТОЕ ДОСЬЕ'){return `<div class="page-head"><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(title)}</h1>${description?`<p class="lead">${esc(description)}</p>`:''}</div>`;}
function inline(text){
 return esc(text).replace(/https?:\/\/[^\s<>]+/g,u=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${u}</a>`).replace(/\[([a-f0-9]{12})\]/g,(m,id)=>S.has(id)?`<button class="citation" data-source="${id}">${id}</button>`:m);
}
function md(text){
 let count=0;
 return text.split(/\n\s*\n/).map(block=>{
  if(/^#{1,3} /.test(block)){const lines=block.split('\n');const level=lines[0].match(/^#+/)[0].length;return `<h${level} id="reading-${count++}">${inline(lines[0].replace(/^#+ /,''))}</h${level}>${lines.length>1?`<p>${inline(lines.slice(1).join('\n'))}</p>`:''}`;}
  if(block.split('\n').every(x=>/^[-*] /.test(x)))return '<ul>'+block.split('\n').map(x=>'<li>'+inline(x.slice(2))+'</li>').join('')+'</ul>';
  return '<p>'+inline(block).replace(/\n/g,'<br>')+'</p>';
 }).join('');
}
function claimCard(c){return `<article class="list-item"><div class="list-top">${badge(c.grade)}<span>${esc(c.topic)}${c.date?' · '+esc(c.date):''}</span><span>${esc(c.nature)}</span></div><h3><a href="#finding/${c.id}">${esc(c.title)}</a></h3><p>${esc(c.body)}</p>${objects(c.objects)}${sources(c.sources)}</article>`;}
function entityCard(e){return `<a class="card card-link" href="#entity/${e.id}"><div class="meta"><span>${esc(e.kind)}</span><span>${esc(e.country)}</span></div><h3>${esc(e.name)}</h3><p>${esc(e.summary)}</p>${e.closed?neutral('Историческая · ликвидирована'):e.excluded?neutral('Связь не установлена'):''}<div class="card-foot"><span>Полное досье и источники</span><span>↗</span></div></a>`;}
function showDialog(title,html){$('#dialog-body').innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${html}`;const d=$('#evidence-dialog');if(!d.open)d.showModal();}
function sourceDialog(id){
 const s=S.get(id);if(!s)return;
 const claims=D.claims.filter(c=>c.sources.includes(id));
 showDialog(s.title||'Источник: '+id,`<p class="original-url">${esc(s.url)}</p><dl><dt>Издатель / домен</dt><dd>${esc(s.publisher)}</dd><dt>Обращение, UTC</dt><dd>${esc(s.accessed)}</dd><dt>Результат</dt><dd>${esc(s.error||'HTTP '+s.status)} · ${esc(s.characters||0)} символов извлечено</dd><dt>Роль</dt><dd>${s.used?'Использован в аналитике':'Поисковый, технический или недоступный источник'}</dd></dl>${s.sha256?`<p class="source-hash">SHA-256: ${esc(s.sha256)}</p>`:''}<div class="callout">HTTP 200 и наличие файла не подтверждают истинность всех содержащихся утверждений. Самозаявления и вторичные данные отмечены в досье.</div>${claims.length?`<h3>Что подтверждается этим источником</h3>${claims.map(c=>`<a class="related-item" href="#finding/${c.id}">${badge(c.grade)} ${esc(c.title)}<span>${esc(c.location||c.nature)}</span></a>`).join('')}`:'<p>Содержательные выводы привязаны к досье либо этот запрос не использован как доказательство.</p>'}<div class="actions"><a class="button primary" href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">Открыть первоисточник ↗</a><a class="button" href="#source/${id}">Карточка источника</a></div>`);
}
const adjacency=new Map(D.entities.map(e=>[e.id,[]]));
for(const edge of D.edges){adjacency.get(edge.source)?.push({node:edge.target,edge});adjacency.get(edge.target)?.push({node:edge.source,edge});}
const findEdge=(a,b)=>D.edges.find(e=>(e.source===a&&e.target===b)||(e.source===b&&e.target===a));
const weakest=edges=>edges.reduce((g,e)=>e.grade>g?e.grade:g,'A');
function getPath(a,b,allowed=D.edges){
 if(a===b)return {nodes:[a],edges:[]};
 const adj=new Map(D.entities.map(e=>[e.id,[]]));for(const e of allowed){adj.get(e.source)?.push([e.target,e]);adj.get(e.target)?.push([e.source,e]);}
 const q=[[a]],seen=new Set([a]);while(q.length){const path=q.shift(),last=path.at(-1);for(const [next,e] of adj.get(last)||[]){if(seen.has(next))continue;const np=[...path,next];if(next===b)return {nodes:np,edges:np.slice(1).map((x,i)=>allowed.find(e=>(e.source===np[i]&&e.target===x)||(e.target===np[i]&&e.source===x)))};seen.add(next);q.push(np);}}
 return null;
}
function alternativePaths(a,b,allowed=D.edges){
 const queue=[[a]],results=[];let inspected=0;
 while(queue.length&&results.length<4&&inspected++<2500){
  const path=queue.shift(),last=path.at(-1);
  if(last===b){results.push({nodes:path,edges:path.slice(1).map((id,i)=>allowed.find(e=>(e.source===path[i]&&e.target===id)||(e.target===path[i]&&e.source===id)))});continue;}
  if(path.length>5)continue;
  const neighbours=new Set(allowed.filter(e=>e.source===last||e.target===last).map(e=>e.source===last?e.target:e.source));
  for(const id of neighbours)if(!path.includes(id))queue.push([...path,id]);
 }
 return results;
}
function networkGroups(){
 const groups=[['Собственность и прежние компании',e=>e.kind.includes('собственность'),'Здесь объединяются только сведения о долях. Ликвидированные общества остаются историческими.'],['Редакционная работа и издатели',e=>['выходные данные','редакционная','дистрибуция'].includes(e.kind),'Учредительство издания, издательская работа и размещение PDF — разные отношения.'],['Профессиональная и общественная среда',e=>['институциональная','профессиональная'].includes(e.kind),'Назначения и профессиональные роли не приравниваются к бюджетному финансированию агентства.']];
 return `<section class="section"><h2>Основные группы отношений</h2><div class="grid">${groups.map(([title,test,explanation])=>{const es=D.edges.filter(test),degree=new Map();for(const e of es){degree.set(e.source,(degree.get(e.source)||0)+1);degree.set(e.target,(degree.get(e.target)||0)+1);}const centres=[...degree].sort((a,b)=>b[1]-a[1]).slice(0,3);return `<div class="card"><h3>${esc(title)}</h3><p>${esc(explanation)}</p><p>${es.length} отдельных отношений. Наиболее связные узлы в этой группе:</p>${objects(centres.map(x=>x[0]))}</div>`;}).join('')}</div><p class="notice">Группы сформированы по типу отношения, центры — по числу рёбер внутри группы. Это описание собранного корпуса, не оценка реального влияния или скрытого контроля.</p></section>`;
}
function recommend(){
 const found=[],seen=new Set();
 const add=(nodes,title,body,score)=>{if(nodes.length<3||new Set(nodes).size!==nodes.length)return;const es=nodes.slice(1).map((n,i)=>findEdge(nodes[i],n));if(es.some(x=>!x))return;const key=[...nodes].sort().join('|');if(seen.has(key))return;seen.add(key);found.push({id:'chain-'+found.length,nodes,edges:es,title,body,score,grade:weakest(es)});};
 const board=D.edges.filter(e=>e.target==='eia'&&e.kind==='публичное заявление');
 const ownerEdges=D.edges.filter(e=>e.kind.includes('собственность'));
 for(const b of board){
  const businesses=ownerEdges.filter(e=>e.source===b.source);
  for(const business of businesses){
   const other=ownerEdges.filter(e=>e.target===business.target&&e.source!==b.source);
   const historical=!!business.end;
   for(const o of other){
    let nodes=['eia',b.source,business.target,o.source];
    const next=ownerEdges.filter(e=>e.source===o.source&&!nodes.includes(e.target)&&!e.end).sort((a,b)=>Number(b.target==='meat')-Number(a.target==='meat'))[0];
    if(next&&!historical)nodes.push(next.target);
    add(nodes,`Общий бизнес: ${shortName(b.source)} и ${shortName(o.source)}`,historical?'Исторические доли и повторяющиеся партнёры. Даты ликвидации ограничивают смысл этой цепочки; нынешнее влияние на EIA не установлено.':'В публичном руководстве EIA и корпоративных карточках встречаются одни и те же люди. Доля в другой компании не доказывает владение EIA или денежный перевод.',historical?6:12+(next?3:0));
   }
   if(!other.length)add(['eia',b.source,business.target],`Другой бизнес: ${shortName(b.source)}`,historical?'Историческое участие: компания уже ликвидирована.':'Корпоративная роль участника публичного совета EIA. Отдельное юридическое лицо и отдельная отчётность.',historical?4:9);
  }
 }
 for(const media of D.entities.filter(e=>e.kind==='СМИ')){
  if(!findEdge('eia',media.id))continue;
  for(const e of D.edges.filter(e=>e.target===media.id&&e.kind==='выходные данные')){
   if(e.source==='eia')continue;
   add(['eia',media.id,e.source],`Кто выпускает ${media.name.replace('Журнал ','')}`,`Файл в каталоге EIA → конкретное издание → ${e.relation.toLocaleLowerCase('ru')}. Дистрибуция не равна владению.`,e.source==='mpsu'?11:8);
  }
 }
 const institutions=D.edges.filter(e=>e.kind==='институциональная');
 for(const b of board)for(const ins of institutions.filter(e=>e.source===b.source)){
  const peers=institutions.filter(e=>e.target===ins.target&&e.source!==b.source);
  if(peers.length)add(['eia',b.source,ins.target,peers[0].source],`Институциональная среда: ${shortName(ins.target)}`,'Публичные профессиональные роли и отдельные заявления о партнёрстве. Цепочка не устанавливает государственный контроль или финансирование.',8);
 }
 const ranked=found.sort((a,b)=>b.score-a.score||a.title.localeCompare(b.title,'ru'));
 return ranked.filter((item,i)=>!ranked.slice(0,i).some(prior=>item.nodes.every(id=>prior.nodes.includes(id))));
}
const recommendations=recommend();
function graphSVG(nodes,edges,compact=false){
 if(!nodes.length)return '<div class="empty">Нет связей, соответствующих фильтрам.</div>';
 const width=900,height=nodes.length<=3?250:nodes.length<=5?340:450;
 const positions=new Map();
 const cols=nodes.length<=3?nodes.length:nodes.length<=5?3:4;
 const rows=Math.ceil(nodes.length/cols);
 nodes.forEach((id,i)=>{const row=Math.floor(i/cols),col=i%cols,reverse=row%2===1;positions.set(id,{x:100+(reverse?cols-1-col:col)*((width-200)/Math.max(1,cols-1)),y:rows===1?height/2:90+row*((height-180)/Math.max(1,rows-1))});});
 const colour={Человек:'#8caec4',Компания:'#d4ad78',НКО:'#8bb09d',СМИ:'#b4a2c2','Судебное дело':'#d7a397'};
 function lines(label,n=23){let result=[],line='';for(const word of label.split(' ')){if((line+' '+word).length>n&&line){result.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)result.push(line);return result.slice(0,4);}
 return `<svg class="network-svg${compact?' compact':''}" viewBox="0 0 ${width} ${height}" role="img" aria-label="Схема документированных отношений; узлы и линии доступны по нажатию"><defs><pattern id="dots" width="23" height="23" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".65" fill="#354151" opacity=".6"/></pattern></defs><rect width="${width}" height="${height}" fill="url(#dots)"/>${edges.map(e=>{const a=positions.get(e.source),b=positions.get(e.target);if(!a||!b)return '';const mx=(a.x+b.x)/2,my=(a.y+b.y)/2;return `<g class="graph-edge" data-edge="${e.id}" role="button" tabindex="0" aria-label="${esc(e.relation)}"><path d="M ${a.x} ${a.y} L ${b.x} ${b.y}" stroke="${e.grade==='A'?'#718f83':'#8c7d64'}" stroke-width="1.4" fill="none" ${e.grade>='C'?'stroke-dasharray="5 5"':''}/><path d="M ${a.x} ${a.y} L ${b.x} ${b.y}" stroke="transparent" stroke-width="24"/><circle cx="${mx}" cy="${my}" r="11" fill="#18212b" stroke="#52604f"/><text x="${mx}" y="${my+3.5}" fill="${e.grade==='A'?'#81b5a1':'#d4ad78'}" text-anchor="middle" font-size="10">${e.grade}</text></g>`;}).join('')}${nodes.map(id=>{const e=E.get(id),p=positions.get(id),label=lines(shortName(id)),nh=68+Math.max(0,label.length-2)*14;return `<g class="graph-node" data-entity="${esc(id)}" tabindex="0" role="link" aria-label="${esc(e.name)}"><rect x="${p.x-86}" y="${p.y-nh/2}" width="172" height="${nh}" rx="5" fill="${id==='eia'?'#2c2b28':'#19232e'}" stroke="${colour[e.kind]||'#8796a8'}" stroke-opacity=".8"/><text x="${p.x}" y="${p.y-nh/2+18}" fill="${colour[e.kind]||'#8796a8'}" font-size="8.5" letter-spacing="1" text-anchor="middle">${esc(e.kind.toLocaleUpperCase('ru'))}</text>${label.map((l,i)=>`<text x="${p.x}" y="${p.y-nh/2+37+i*14}" fill="#e0e5e9" text-anchor="middle" font-size="11">${esc(l)}</text>`).join('')}</g>`;}).join('')}</svg>`;
}
function graphPanel(path,{steps=false,title='Отдельные отношения, а не общий контроль'}={}){
 const n=steps?Math.max(2,Math.min(state.step+1,path.nodes.length)):path.nodes.length;
 const nodes=path.nodes.slice(0,n),edges=path.edges.filter(e=>nodes.includes(e.source)&&nodes.includes(e.target));
 return `<div class="graph-panel"><div class="graph-toolbar"><span class="eyebrow" style="margin:0">${esc(title)}</span><small>${nodes.length} объектов · ${edges.length} отношений</small></div><div class="graph-wrap">${graphSVG(nodes,edges)}</div>${steps?`<div class="step-text">${state.step>=path.edges.length?'<strong>Вся цепочка раскрыта.</strong> Нажмите на линию, чтобы увидеть источник и период, или на узел, чтобы прочитать досье.':`<strong>Шаг ${state.step} из ${path.edges.length}.</strong> ${esc(path.edges[Math.max(0,state.step-1)]?.relation||'Выберите следующий шаг.')}`}</div><div class="graph-caption"><div class="step-controls"><button class="button" data-action="step-back" ${state.step<=1?'disabled':''}>← Назад</button><button class="button primary" data-action="step-next" ${state.step>=path.edges.length?'disabled':''}>Следующее звено →</button><span>${badge(weakest(path.edges))}</span></div></div>`:''}<div class="graph-caption">Сплошная линия: A/B. Пунктир: C/D. Направление и правовой смысл указаны в карточке каждого отношения. Исторические доли не означают текущую связь. Путь не доказывает финансирование.</div></div>`;
}
function chainCard(r){return `<article class="card chain-card ${state.chain===r.id?'selected':''}" data-chain="${r.id}" tabindex="0" role="button" aria-label="Исследовать цепочку ${esc(r.title)}"><div class="meta">${badge(r.grade)}<span>${r.edges.length-1} промежуточных звеньев</span></div><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p><div class="chain-line">${r.nodes.map((id,i)=>(i?'<i>→</i>':'')+`<span>${esc(shortName(id))}</span>`).join('')}</div><div class="card-foot"><span>Раскрыть по шагам</span><span>↗</span></div></article>`;}
function home(){
 const highlights=[['c01','01','Документы говорят разное'],['c05','02','Общий бизнес за пределами медиа'],['c07','03','История под прежней фамилией']];
 content.innerHTML=crumbs('Главные результаты')+`<section class="hero"><div><span class="eyebrow">EIA MEDIA · ИССЛЕДОВАНИЕ ОТКРЫТЫХ ИСТОЧНИКОВ</span><h1>Кто стоит за EIA?</h1><p class="lead">Люди, деловые связи и документы, которые помогают понять устройство агентства. От проверяемого факта — к источнику. От публичного заявления — к вопросу, который ещё предстоит разрешить.</p><div class="actions"><a class="button primary" href="#archive/FULL_REPORT.md">Читать расследование <span>→</span></a><a class="button subtle" href="#explore">Исследовать связи</a></div><div class="stat-strip"><span><strong>${D.entities.length}</strong> исследованных объектов</span><span><strong>${D.claims.length}</strong> существенных утверждения</span><span>Датированный срез · 21.10.2026</span></div></div><svg class="hero-art" viewBox="0 0 330 290" role="img" aria-label="Иллюстрация исследованной цепочки EIA, Рабинович, Евразийский рейтинг, Палагутин"><g fill="none" stroke="#71644e" stroke-dasharray="4 4"><path d="M165 60L55 150L165 245L275 150L165 60"/></g><circle cx="165" cy="60" r="36" fill="#292a28" stroke="#d4ad78"/><text x="165" y="68" fill="#d4ad78" text-anchor="middle" font-family="Georgia" font-size="26">EIA</text><g fill="#18222e" stroke="#6e8497"><circle cx="55" cy="150" r="25"/><circle cx="275" cy="150" r="25"/></g><g fill="#d4ad78" font-size="9" text-anchor="middle" font-family="system-ui"><text x="55" y="193">Рабинович</text><text x="275" y="193">Палагутин</text></g><circle cx="165" cy="245" r="25" fill="#262723" stroke="#b19b74"/><text x="165" y="248" fill="#d4ad78" font-family="Georgia" font-size="16" text-anchor="middle">50/50</text><text x="165" y="284" fill="#a0adbb" font-family="system-ui" font-size="9" text-anchor="middle">«Евразийский рейтинг» · данные агрегаторов</text></svg></section><div class="callout"><strong>Граница знания.</strong> Конечные акционеры АО и подтверждённые источники финансирования EIA не установлены. Деловые связи руководителей не равны контролю над агентством. <a href="#method">Как оценивались доказательства ↗</a></div><section class="section"><div class="section-heading"><h2>С чего начать</h2><small>Три находки с понятным контекстом<br>и проверяемой доказательной базой</small></div><div class="grid">${highlights.map(([id,no,title])=>{const c=C.get(id);return `<a class="card card-link" href="#finding/${id}"><span class="card-number">${no} / НАХОДКА</span><div class="meta">${badge(c.grade)}<span>${c.sources.length} ссылок</span></div><h3>${title}</h3><p>${esc(c.body)}</p><div class="card-foot"><span>Что обнаружено и чем подтверждено</span><span>↗</span></div></a>`;}).join('')}</div></section><section class="section"><div class="section-heading"><h2>Выберите направление</h2><small>Маршруты сформированы из утверждений корпуса. Пустые темы не заполняются примерами.</small></div><div class="topic-row">${topics().map(t=>`<a class="topic" href="#topic/${encodeURIComponent(t)}">${esc(t)}<span>${D.claims.filter(c=>c.topic===t).length} →</span></a>`).join('')}</div></section><section class="section"><div class="section-heading"><h2>Через кого связаны компании</h2><a class="button subtle" href="#explore">Все рекомендации →</a></div><div class="grid two recommendation">${recommendations.slice(0,2).map(chainCard).join('')}</div></section><section class="section"><div class="section-heading"><h2>Ключевые фигуры</h2><a class="button subtle" href="#entities">Все объекты →</a></div><div class="grid">${['rabinovich','grebenskova','palagutin'].map(id=>entityCard(E.get(id))).join('')}</div></section><p class="notice">Корпус включает успешные обращения, неуспешные запросы и непроверенные зацепки. Все собственные аналитические материалы доступны целиком. Это независимый материал, не публикация EIA Media.</p>`;
}
const topics=()=>[...new Set(D.claims.map(c=>c.topic))];
function topicPage(topic){
 const list=D.claims.filter(c=>c.topic===topic);
 content.innerHTML=crumbs(topic)+head(topic,'Все существенные утверждения по этому направлению. Открывайте источники и полные досье, чтобы оценить контекст и ограничения.')+`<div class="chips">${topics().map(t=>`<a class="chip ${t===topic?'active':''}" href="#topic/${encodeURIComponent(t)}">${esc(t)}</a>`).join('')}</div><section class="section list">${list.map(claimCard).join('')||'<div class="empty">Для этой темы в корпусе пока нет утверждений.</div>'}</section>`;
}
function finding(id){
 const c=C.get(id);if(!c)return notFound();
 content.innerHTML=crumbs('Находка', ['topic/'+encodeURIComponent(c.topic),c.topic])+head(c.title,c.nature,'НАХОДКА · '+c.id.toUpperCase())+`<div class="split"><article><div class="eyebrow-line">${badge(c.grade)}<span class="muted">${esc(c.date)}</span></div><div class="prose"><p>${esc(c.body)}</p></div>${c.quote?`<div class="callout"><strong>Короткая цитата</strong><p>${esc(c.quote)}</p><small>${esc(c.location)}</small></div>`:''}<h2 class="section">Проверить основание</h2>${c.sources.map(s=>sourceItem(S.get(s),true)).join('')}<div class="callout">Категория относится к сформулированному утверждению. Документированное наличие текста в PDF не подтверждает автоматически его юридическую достоверность.</div>${id==='c01'||['c02','c03','c04'].includes(id)?comparisonCards():''}<h2 class="section">Участники и контекст</h2>${objects(c.objects)}</article><aside><div class="side-card"><h3>Логичный следующий шаг</h3>${recommendations.filter(r=>r.nodes.some(n=>c.objects.includes(n))).slice(0,3).map(r=>`<a class="related-item" href="#explore/${r.id}">${esc(r.title)}<span>Отдельные отношения · ${r.grade}</span></a>`).join('')}</div><div class="side-card"><h3>Открытые вопросы</h3>${D.leads.filter(l=>c.objects.includes(l.object)).slice(0,4).map(l=>`<a class="related-item" href="#lead/${l.id}">${esc(l.title)}<span>${esc(l.priority)} приоритет</span></a>`).join('')||'<a href="#leads">Все незавершённые проверки →</a>'}</div></aside></div>`;
}
function entityPage(id){
 const e=E.get(id);if(!e)return notFound();
 const relations=adjacency.get(id)||[],relatedClaims=D.claims.filter(c=>c.objects.includes(id)),photo=D.photos.find(p=>p.object===id);
 const smallGraph={nodes:[id,...[...new Set(relations.map(r=>r.node))].slice(0,7)],edges:[]};smallGraph.edges=D.edges.filter(r=>smallGraph.nodes.includes(r.source)&&smallGraph.nodes.includes(r.target));
 const fields=[['Тип',e.kind],['Юрисдикция',e.country],['ИНН',e.inn],['ОГРН',e.ogrn],['Регистрация',e.registered],['Капитал',e.capital===undefined?'':money(e.capital)],['Статус',e.status],['Ликвидация',e.closed]].filter(x=>x[1]);
 content.innerHTML=crumbs(e.name,['entities','Люди и организации'])+head(e.name,e.summary,e.kind.toLocaleUpperCase('ru'))+`<div class="split"><article>${e.excluded?'<div class="callout">Этот объект сохранён для проверки одноимённости. Доказанного пути к EIA нет; он не включён в основную сеть.</div>':''}<div class="fact-grid">${fields.map(([k,v])=>`<div class="fact-cell"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="prose">${md(e.body)}</div>${e.aliases?.length?`<p class="notice">Варианты названия: ${esc(e.aliases.join(' · '))}</p>`:''}<h2 class="section">Основания досье</h2>${sources(e.sources)}<div class="callout">Раздел объединяет разные по весу сведения. Самозаявления и данные агрегаторов сохранены с атрибуцией; подробная оценка доступна в связанных находках.</div><section class="section"><div class="section-heading"><h2>Ближайшие отношения</h2><small>Небольшая группа, не вся сеть</small></div>${relations.length?graphPanel(smallGraph,{title:'Контекст объекта'}):'<div class="empty">Подтверждённых отношений в собранном графе нет.</div>'}<div class="list section">${relations.map(({node,edge})=>`<div class="list-item"><div class="list-top">${badge(edge.grade)}<span>${esc(edge.period)}${edge.end?' · до '+esc(edge.end):''}</span><span>${esc(edge.kind)}</span></div><h3><a href="#entity/${node}">${esc(E.get(node).name)}</a></h3><p>${esc(edge.relation)}</p><button class="button" data-edge="${edge.id}">Смысл и доказательства</button></div>`).join('')}</div></section>${relatedClaims.length?`<h2 class="section">Все находки с этим участником</h2><div class="list">${relatedClaims.map(claimCard).join('')}</div>`:''}</article><aside>${photo?`<div class="side-card">${imageBlock(photo.url,photo.caption,'photo-frame')}<p class="photo-credit">Портрет опубликован EIA.<br>Лицензия на перепубликацию не установлена.<br><button class="citation" data-source="${photo.source}">Источник и происхождение</button></p></div>`:''}<div class="side-card"><h3>Исследовать дальше</h3>${recommendations.filter(r=>r.nodes.includes(id)).slice(0,3).map(r=>`<a class="related-item" href="#explore/${r.id}">${esc(r.title)}<span>${r.edges.length} отдельных отношений · ${r.grade}</span></a>`).join('')||'<p>Автоматическая рекомендация отсутствует: содержательная цепочка не установлена.</p>'}</div><div class="side-card"><h3>События</h3>${D.timeline.filter(t=>t.objects.includes(id)).slice(-5).map(t=>`<a class="related-item" href="#timeline">${esc(t.title)}<span>${esc(t.date)}</span></a>`).join('')||'<p>Датированные события не установлены.</p>'}</div><div class="side-card"><h3>Что проверить</h3>${D.leads.filter(l=>l.object===id).map(l=>`<a class="related-item" href="#lead/${l.id}">${esc(l.title)}<span>${esc(l.priority)} приоритет</span></a>`).join('')||'<p>Документальные ограничения описаны в досье.</p>'}</div></aside></div>`;
}
function directory(){
 const kinds=[...new Set(D.entities.map(e=>e.kind))],countries=[...new Set(D.entities.map(e=>e.country))];
 content.innerHTML=crumbs('Люди и организации')+head('Люди и организации','Все исследованные объекты, включая исторические компании, неустановленные связи и исключённые совпадения. Карточки ведут к полному досье.')+`<div class="filterbar"><input id="entity-query" aria-label="Поиск объектов" placeholder="Имя, прежняя фамилия, ИНН, роль…" value="${esc(state.entityQuery)}"><label class="sr-only" for="entity-kind">Тип объекта</label><select id="entity-kind"><option value="">Все типы</option>${kinds.map(k=>`<option ${state.entityKind===k?'selected':''}>${esc(k)}</option>`).join('')}</select><label class="sr-only" for="entity-country">Страна</label><select id="entity-country"><option value="">Все юрисдикции</option>${countries.map(k=>`<option ${state.entityCountry===k?'selected':''}>${esc(k)}</option>`).join('')}</select></div><p id="entity-count" class="notice"></p><div class="grid" id="entity-results"></div>`;filterEntities();
}
function filterEntities(){const list=D.entities.filter(e=>(!state.entityKind||e.kind===state.entityKind)&&(!state.entityCountry||e.country===state.entityCountry)&&match(JSON.stringify(e),state.entityQuery));$('#entity-count').textContent=`Найдено ${list.length} из ${D.entities.length}. Исторические компании помечены отдельно.`;$('#entity-results').innerHTML=list.map(entityCard).join('')||'<div class="empty">Объект не найден. Попробуйте вариант имени или корпоративный номер.</div>';}
function allowedEdges(){return D.edges.filter(e=>(!state.graphGrade||e.grade===state.graphGrade)&&(!state.graphPeriod||(state.graphPeriod==='current'?!e.end:!!e.end))&&(!state.graphKind||e.kind===state.graphKind)&&(!state.graphCountry||[e.source,e.target].some(id=>E.get(id).country===state.graphCountry))&&(!state.graphNodeKind||[e.source,e.target].some(id=>E.get(id).kind===state.graphNodeKind)));}
function explore(chainId){
 if(chainId&&recommendations.some(r=>r.id===chainId)){if(state.chain!==chainId){state.chain=chainId;state.step=1;state.path=null;}}
 if(!state.chain)state.chain=recommendations[0]?.id;
 const allowed=allowedEdges(),allowedIds=new Set(allowed.map(e=>e.id)),filtered=recommendations.filter(r=>r.edges.every(e=>allowedIds.has(e.id)));
 let selected=state.path||recommendations.find(r=>r.id===state.chain);
 if(!state.path&&selected&&!filtered.includes(selected)){selected=filtered[0];state.chain=selected?.id;}
 const kinds=[...new Set(D.edges.map(e=>e.kind))];
 content.innerHTML=crumbs('Исследовать связи')+head('Связи, которые имеют смысл','Рекомендации автоматически строятся из владения, руководства, редакционных и институциональных ролей. Исторические связи и самозаявления не превращаются в доказанный контроль.')+`<div class="filterbar"><label for="graph-grade">Достоверность</label><select id="graph-grade"><option value="">A–D: весь корпус</option>${Object.entries(gradeNames).map(([g,n])=>`<option value="${g}" ${state.graphGrade===g?'selected':''}>${g} · ${n}</option>`).join('')}</select><label class="sr-only" for="graph-period">Период</label><select id="graph-period"><option value="">Все периоды</option><option value="current" ${state.graphPeriod==='current'?'selected':''}>Без завершённых исторических долей</option><option value="past" ${state.graphPeriod==='past'?'selected':''}>Завершённые исторические доли</option></select><label class="sr-only" for="graph-kind">Отношение</label><select id="graph-kind"><option value="">Все отношения</option>${kinds.map(k=>`<option ${state.graphKind===k?'selected':''}>${esc(k)}</option>`).join('')}</select><label class="sr-only" for="graph-country">Юрисдикция</label><select id="graph-country"><option value="">Все юрисдикции</option>${[...new Set(D.entities.map(e=>e.country))].map(k=>`<option ${state.graphCountry===k?'selected':''}>${esc(k)}</option>`).join('')}</select><label class="sr-only" for="graph-node-kind">Тип узла</label><select id="graph-node-kind"><option value="">Все типы объектов</option>${[...new Set(D.entities.map(e=>e.kind))].map(k=>`<option ${state.graphNodeKind===k?'selected':''}>${esc(k)}</option>`).join('')}</select><button class="button" data-action="reset-graph">Сбросить</button></div><section id="active-chain">${selected?`<div class="section-heading"><div><h2>${esc(selected.title||'Выбранный путь')}</h2><p class="muted">${esc(selected.body||'Кратчайший путь в собранном графе. Смысл каждого отношения проверяйте отдельно.')}</p></div></div>${graphPanel(selected,{steps:true,title:'Последовательность отдельных отношений'})}`:graphPanel({nodes:[...new Set(allowed.flatMap(e=>[e.source,e.target]))].slice(0,8),edges:allowed.slice(0,8)},{title:'Отношения по фильтру'})}</section>${state.path&&state.alternatives.length>1?`<div class="section"><h3>Другие пути между выбранными объектами</h3><div class="list">${state.alternatives.map((p,i)=>`<button class="button" data-alternative="${i}">${esc(p.nodes.map(shortName).join(' → '))} · ${weakest(p.edges)}</button>`).join('')}</div><p class="notice">Альтернативы могут проходить через редакционное участие или опубликованное заявление. Каждый путь объясняет только свои отдельные звенья.</p></div>`:''}${networkGroups()}<section class="section recommendation"><div class="section-heading"><h2>Рекомендованные маршруты</h2><small>Приоритет: собственность, конкретные роли, прямота пути и доступность доказательств.</small></div><div class="grid two">${filtered.slice(0,12).map(chainCard).join('')||'<div class="empty">Целых рекомендованных цепочек по этим фильтрам нет. Отдельные отношения приведены ниже.</div>'}</div></section><details class="section"><summary>Найти путь между любыми двумя объектами</summary><p class="notice">Дополнительный инструмент. Кратчайший путь не доказывает юридическую аффилированность.</p><div class="path-controls"><select id="path-from" aria-label="Начало пути">${D.entities.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select><span>→</span><select id="path-to" aria-label="Конец пути">${D.entities.map(e=>`<option value="${e.id}" ${e.id==='meat'?'selected':''}>${esc(e.name)}</option>`).join('')}</select><button class="button primary" data-action="find-path">Найти</button></div><div id="path-status" aria-live="polite"></div></details><details class="section"><summary>Все отношения, соответствующие фильтрам (${allowed.length})</summary><div class="list section">${allowed.map(e=>`<div class="list-item"><div class="list-top">${badge(e.grade)}<span>${esc(e.period)}${e.end?' — '+esc(e.end):''}</span></div><p>${esc(shortName(e.source))} → ${esc(shortName(e.target))}</p><button class="button" data-edge="${e.id}">${esc(e.relation)}</button></div>`).join('')}</div></details><div class="callout">Центры графа здесь — прежде всего люди с несколькими опубликованными ролями. Число связей зависит от доступности источников и не является мерой реального влияния.</div>`;
}
function edgeDialog(id){const e=G.get(id);if(!e)return;showDialog(e.relation,`${objects([e.source,e.target])}<p class="notice">Направление отношения: ${esc(shortName(e.source))} → ${esc(shortName(e.target))}</p><p class="section">${badge(e.grade)} · ${esc(e.kind)}</p><dl><dt>Период</dt><dd>${esc(e.period||'Не установлен')}${e.end?' · завершение '+esc(e.end):''}</dd><dt>Смысл связи</dt><dd>${esc(e.significance)}</dd></dl>${sources(e.sources)}<div class="callout">Путь через этот узел не доказывает владение, финансирование или сотрудничество между всеми участниками цепочки.</div>`);}
function timelinePage(){const years=[...new Set(D.timeline.map(e=>e.date.slice(0,4)))].sort();content.innerHTML=crumbs('Хронология')+head('Несколько историй во времени','Регистрация домена, создание юридического лица, дата выпуска и назначение — разные события. Точность даты сохранена из источника.')+`<label class="muted" for="timeline-year">Год </label><select class="timeline-filter" id="timeline-year"><option value="">Все годы</option>${years.map(y=>`<option>${y}</option>`).join('')}</select><div class="timeline" id="timeline-results"></div>`;filterTimeline('');}
function filterTimeline(year){$('#timeline-results').innerHTML=D.timeline.filter(e=>!year||e.date.startsWith(year)).map(e=>`<article class="time-item"><time>${esc(e.date)}</time><div class="list-top">${badge(e.grade)}</div><h3>${esc(e.title)}</h3><p>${esc(e.body)}</p>${objects(e.objects)}${sources(e.sources)}</article>`).join('');}
function finance(){const known=D.financials.filter(f=>f.revenue!==null),max=Math.max(...known.map(f=>f.revenue));content.innerHTML=crumbs('Деньги и финансирование')+head('Деньги: отдельные компании, разные периоды','Подтверждённый бюджет EIA не установлен. Ни оборот компании руководителя, ни господдержка другого бизнеса не являются автоматически доходом агентства.')+`<div class="callout"><strong>Данные ниже — категория C.</strong> Финансовые значения получены из агрегаторов. Подписанные первичные формы ГИР БО не удалось получить (503). Суммы не консолидированы в «оборот холдинга».</div><div class="split"><section class="card"><h2>Выручка исследованных компаний</h2><p class="muted">Линейная шкала · рубли · периоды указаны отдельно</p>${known.map(f=>`<div class="bar-row"><div class="bar-label"><a href="#entity/${f.object}">${esc(shortName(f.object))} · ${f.year}</a><strong>${money(f.revenue)}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${f.revenue/max*100}%"></div></div></div>`).join('')}<p class="chart-note">Нулевая выручка НКО не раскрывает целевые поступления. Отсутствие значения у EIA — неизвестность, а не ноль.</p></section><aside><div class="side-card"><span class="eyebrow">EIA / АО</span><h2>Бюджет неизвестен</h2><p>Регистрация в 2026 году. Источники текущего содержания редакции, инвесторы и договоры финансирования не установлены.</p><a class="button subtle" href="#lead/l03">Что нужно получить →</a></div></aside></div><section class="section"><h2>Числа и ограничения</h2><div class="table-scroll"><table class="money-table"><thead><tr><th>Объект / период</th><th>Выручка</th><th>Прибыль</th><th>Как читать</th></tr></thead><tbody>${D.financials.map(f=>`<tr><td><a href="#entity/${f.object}">${esc(shortName(f.object))}</a><br><small>${f.year} · ${f.grade}</small></td><td class="nowrap">${money(f.revenue)}</td><td class="nowrap">${money(f.profit)}</td><td>${esc(f.note)}${sources(f.sources)}</td></tr>`).join('')}</tbody></table></div></section><section class="section list">${['c09','c10','c15','c16'].map(id=>claimCard(C.get(id))).join('')}</section><div class="actions"><a href="#archive/FINANCES.md" class="button">Полный финансовый разбор →</a></div>`;}
function comparisonCards(){return D.comparisons.map(c=>`<article class="card section"><div class="meta">${badge('A','Расхождение текстов')}<a href="#entity/${c.object}">Досье издания ↗</a></div><h3>${esc(c.name)}</h3><div class="comparison"><div><span>Контакты EIA</span><strong>${esc(c.web)}</strong></div><div class="pdf"><span>Выходные данные PDF</span><strong>${esc(c.pdf)}</strong><small>Страница PDF ${c.page}</small></div></div>${sources(c.sources)}<p class="notice">Юридически актуальная регистрация не установлена. Разные виды СМИ могут иметь разные свидетельства; официальный реестр необходим для проверки.</p></article>`).join('');}
function documents(){content.innerHTML=crumbs('Сверка документов')+head('Сравните два первичных текста','На контактной странице и в выходных данных PDF опубликованы разные реквизиты. Это проверенное наблюдение о содержимом, а не заключение о подлинности свидетельств.')+comparisonCards()+`<div class="callout">Для MIC самостоятельный сайт журнала согласован с его PDF. В реестре Роскомнадзора эти сведения пока не сверены: сервис вернул 503. Официальное подтверждение остаётся открытой задачей.</div><section class="section"><h2>Все существенные наблюдения о документах</h2><div class="list">${D.claims.filter(c=>c.topic==='Документы'||c.id==='c31').map(claimCard).join('')}</div></section>`;}
function imageBlock(url,label,extra=''){return `<div class="image-frame ${extra}"><span class="image-label">${esc(label.split(':')[0])}</span><button class="button image-button" data-image-load="${esc(url)}" data-image-caption="${esc(label)}">Показать оригинал EIA ↗</button></div>`;}
function catalogue(){content.innerHTML=crumbs('Журналы и изображения')+head('Все карточки каталога EIA','40 записей, извлечённых из публичной страницы и переданных ей данных. Каталог подтверждает представление выпусков на сайте, а не владение изданием или фактический тираж.')+`<div class="callout">Все тексты, графы и собственные аналитические материалы работают без интернета. Портреты и обложки принадлежат исходным издателям: свободная лицензия не установлена. Оригинал загружается с EIA только по вашему нажатию; полного копирования произведений нет. При загрузке изображение можно увеличить.</div><div class="filterbar"><input id="catalogue-query" aria-label="Поиск по журналам" placeholder="Издание, герой обложки, год…" value="${esc(state.catalogueQuery)}"></div><p id="catalogue-count" class="notice"></p><div class="issue-grid" id="catalogue-results"></div><section class="section"><h2>Портреты публичного руководства</h2><div class="issue-grid">${D.photos.map(p=>`<article class="issue-card">${imageBlock(p.url,p.caption)}<h3><a href="#entity/${p.object}">${esc(p.caption)}</a></h3><p>Происхождение: страница руководства EIA. Лицензия не установлена.</p>${sources([p.source])}</article>`).join('')}</div></section>`;filterCatalogue();}
function filterCatalogue(){const list=D.catalogue.filter(x=>match(x.title+' '+x.label,state.catalogueQuery));$('#catalogue-count').textContent=`${list.length} из ${D.catalogue.length} карточек. Семь ранних выпусков извлечены из публичных данных страницы, а не только из первоначально раскрытых карточек.`;$('#catalogue-results').innerHTML=list.map(x=>`<article class="issue-card">${imageBlock(x.image,x.title)}<h3>${esc(x.title)}</h3><p>${esc(x.label)}</p><p>${x.hasPdf?'Ссылка на PDF в оригинальном каталоге.':'Отдельный PDF в записи каталога не указан.'}</p><a class="button subtle" href="${safeURL(x.url)}" target="_blank" rel="noopener noreferrer">${x.hasPdf?'Открыть выпуск':'Каталог EIA'} ↗</a>${sources([x.source])}</article>`).join('')||'<div class="empty">Карточки не найдены.</div>';}
function sourceItem(s,full=false){if(!s)return '';return `<article class="list-item"><div class="list-top">${neutral(s.kind)}<span>${esc(s.publisher)}</span><span class="${s.error?'source-error':''}">${esc(s.error||'HTTP '+s.status)}</span></div><h3><button class="citation" data-source="${s.id}">${s.id}</button> <a href="#source/${s.id}">${esc(s.title||s.url)}</a></h3><p>Обращение: ${esc(s.accessed.slice(0,19).replace('T',' '))} UTC · ${esc(s.characters||0)} извлечённых символов.</p>${full?`<p class="source-hash">${esc(s.url)}</p>`:''}<div class="actions"><button class="button" data-source="${s.id}">Контекст и доказательства</button><a class="button subtle" href="${safeURL(s.url)}" target="_blank" rel="noopener noreferrer">Первоисточник ↗</a></div></article>`;}
function sourcePage(id){const s=S.get(id);if(!s)return notFound();content.innerHTML=crumbs('Источник',['sources','Реестр источников'])+head(s.title||s.url,s.publisher,'ИСТОЧНИК · '+s.id)+sourceItem(s,true)+`<p class="section source-hash">SHA-256: ${esc(s.sha256||'Не получен')}</p><section class="section"><h2>Все связанные утверждения</h2><div class="list">${D.claims.filter(c=>c.sources.includes(id)).map(claimCard).join('')||'<p class="muted">Запрос сохранён в журнале; содержательный вывод из него не делался либо он используется в профессиональном досье.</p>'}</div></section><section class="section"><h2>Досье, использующие источник</h2>${objects(D.entities.filter(e=>e.sources.includes(id)).map(e=>e.id))}</section>`;}
function sourcesPage(){content.innerHTML=crumbs('Источники')+head('Проверяемая доказательная база','Здесь сохранены все обращения, включая ошибки и поиск. Число URL не равно числу независимых подтверждений. В карточке видно, какие выводы опираются на источник.')+`<div class="filterbar"><input id="source-query" aria-label="Поиск источников" placeholder="Название, домен, URL, идентификатор…" value="${esc(state.sourceQuery)}"><label class="sr-only" for="source-filter">Роль источника</label><select id="source-filter"><option value="used" ${state.sourceFilter==='used'?'selected':''}>Использованы в аналитике</option><option value="all" ${state.sourceFilter==='all'?'selected':''}>Все обращения</option><option value="failed" ${state.sourceFilter==='failed'?'selected':''}>Недоступные / ошибки</option><option value="search" ${state.sourceFilter==='search'?'selected':''}>Поисковые запросы</option></select></div><p class="notice" id="sources-count"></p><div class="list" id="sources-results"></div><div class="actions" id="sources-pagination"></div>`;filterSources();}
function filterSources(){const list=D.sources.filter(s=>(state.sourceFilter==='all'||(state.sourceFilter==='used'&&s.used)||(state.sourceFilter==='failed'&&s.error)||(state.sourceFilter==='search'&&s.kind==='Поиск'))&&match(JSON.stringify(s),state.sourceQuery));const pages=Math.max(1,Math.ceil(list.length/15));state.sourcePage=Math.min(state.sourcePage,pages-1);$('#sources-count').textContent=`${list.length} из ${D.sources.length} обращений · страница ${state.sourcePage+1} из ${pages}. Пустые HTTP 200 и поисковые фрагменты не считаются проверенным содержимым.`;$('#sources-results').innerHTML=list.slice(state.sourcePage*15,(state.sourcePage+1)*15).map(s=>sourceItem(s)).join('')||'<div class="empty">Источники не найдены.</div>';$('#sources-pagination').innerHTML=`<button class="button" data-action="source-prev" ${state.sourcePage===0?'disabled':''}>← Предыдущие</button><button class="button" data-action="source-next" ${state.sourcePage>=pages-1?'disabled':''}>Следующие →</button>`;}
function leadsPage(id){let list=id?D.leads.filter(x=>x.id===id):D.leads;content.innerHTML=crumbs('Открытые вопросы')+head(id?list[0]?.title||'Вопрос':'Что ещё не установлено','Незавершённые направления доступны целиком. Они не являются установленными обвинениями, скрытыми связями или доказанными финансовыми потоками.')+`<div class="list">${list.map(l=>`<article class="list-item"><div class="list-top">${badge('D')}<span>${esc(l.priority)} приоритет</span></div><h3><a href="#lead/${l.id}">${esc(l.title)}</a></h3><p>${esc(l.body)}</p>${objects([l.object])}</article>`).join('')}</div>${id?'<div class="actions"><a class="button" href="#leads">Все открытые вопросы →</a></div>':''}`;}
const archiveTitles={'FULL_REPORT.md':'Главное расследование','PEOPLE.md':'Профессиональные досье','COMPANIES.md':'Компании и проекты','CONNECTIONS.md':'Цепочки связей','FINDINGS.md':'Все существенные утверждения','TIMELINE.md':'Полная хронология','SOURCES.md':'Все источники и обращения','LEADS.md':'Все открытые направления','FINANCES.md':'Финансы и поддержка','LEGAL.md':'Судебные зацепки','MEDIA.md':'Медиадеятельность и каталог','METHOD.md':'Методика и ограничения','RESEARCH_LOG.md':'Журнал исследования','RESEARCH_PLAN.md':'Исходный план','BRIEF.txt':'Задание пользователя','COVERAGE.md':'Проверка полноты'};
function archive(file='FULL_REPORT.md',query=''){
 const doc=D.documents[file];if(doc===undefined)return notFound();
 content.innerHTML=crumbs('Полные материалы')+head('Полный текст. Без сокращений.','Все подготовленные аналитические файлы доступны здесь целиком. Карточки и граф служат навигацией; исходная аналитика не заменена пересказом.')+`<div class="archive-layout"><nav class="archive-index" aria-label="Полные документы">${Object.keys(D.documents).map(f=>`<a href="#archive/${encodeURIComponent(f)}" class="${file===f?'active':''}">${esc(archiveTitles[f]||f)}</a>`).join('')}</nav><article class="reader"><div class="reader-tools"><span>${esc(file)} · ${doc.length.toLocaleString('ru-RU')} символов</span><a class="button subtle" href="archive/${encodeURIComponent(file)}" download>Скачать оригинал ↓</a></div><div class="prose" id="full-document">${md(doc)}</div></article></div>`;
 if(query)highlightProse(query);
}
function method(){content.innerHTML=crumbs('Методика')+head('Как отличать доказательство от заявления','Уровень достоверности относится к конкретной формулировке, а не ко всему человеку или организации.')+`<div class="grid two">${Object.entries(gradeNames).map(([g,n])=>`<div class="card">${badge(g)}<h3 class="section">${esc(n)}</h3><p>${esc({A:'Документ или надёжное прямое доказательство в указанном смысле. Наличие номера в PDF подтверждает публикацию номера, но не автоматически его юридическую актуальность.',B:'Убедительное внешнее подтверждение с оговорёнными пределами. Например, стороннее СМИ исторически представило человека в конкретной роли.',C:'Предварительная корпоративная запись либо собственное заявление о роли или соглашении. Нужен первичный документ или дополнительная сверка.',D:'Непроверенная зацепка, недостаток идентификации, недоступный судебный акт или открытый вопрос. Не выдаётся за установленную связь.'}[g])}</p></div>`).join('')}</div><section class="section prose">${md(D.meta.method)}</section><div class="actions"><a class="button" href="#archive/METHOD.md">Полная методика в архиве →</a></div>`;}
function snippet(text,q,len=240){const t=String(text).replace(/[#\n]+/g,' '),term=norm(q).split(/\s+/).filter(Boolean)[0]||'',idx=norm(t).indexOf(term),start=Math.max(0,idx-70);return (start?'…':'')+t.slice(start,start+len)+(start+len<t.length?'…':'');}
function highlightText(text,q){const tokens=norm(q).split(/\s+/).filter(Boolean);if(!tokens.length)return esc(text);const re=new RegExp(tokens.map(t=>t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'giu');let out='',last=0;const n=norm(text);for(const m of n.matchAll(re)){out+=esc(text.slice(last,m.index))+'<mark>'+esc(text.slice(m.index,m.index+m[0].length))+'</mark>';last=m.index+m[0].length;}return out+esc(text.slice(last));}
function highlightProse(q){const root=$('#full-document');if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];let n;while((n=walker.nextNode())){if(n.parentElement.closest('button,a'))continue;if(norm(n.textContent).includes(norm(q).split(/\s+/)[0]))nodes.push(n);}for(const n of nodes){const span=document.createElement('span');span.innerHTML=highlightText(n.textContent,q);n.replaceWith(span);}root.querySelector('mark')?.scrollIntoView({block:'center'});}
function searchPage(q){
 const result=[];
 for(const e of D.entities)if(match(JSON.stringify(e),q))result.push({kind:e.kind,title:e.name,text:e.body,href:'#entity/'+e.id,score:match(e.name+' '+(e.aliases||[]).join(' '),q)?100:60});
 for(const c of D.claims)if(match(c.title+' '+c.body,q))result.push({kind:'Находка · '+c.grade,title:c.title,text:c.body,href:'#finding/'+c.id,score:match(c.title,q)?90:55});
 for(const x of D.leads)if(match(x.title+' '+x.body,q))result.push({kind:'Открытый вопрос · D',title:x.title,text:x.body,href:'#lead/'+x.id,score:50});
 for(const t of D.timeline)if(match(t.title+' '+t.body+' '+t.date,q))result.push({kind:'Событие · '+t.date,title:t.title,text:t.body,href:'#timeline',score:35});
 for(const s of D.sources)if(match((s.title||'')+' '+s.url+' '+s.id,q))result.push({kind:'Источник',title:s.title||s.url,text:s.url,href:'#source/'+s.id,score:30});
 for(const x of D.catalogue)if(match(x.title+' '+x.label,q))result.push({kind:'Карточка выпуска',title:x.title,text:x.label,href:'#catalogue-search/'+encodeURIComponent(q),score:45});
 for(const [f,text] of Object.entries(D.documents))if(match(text,q))result.push({kind:'Полный документ',title:archiveTitles[f]||f,text,href:'#archive-search/'+encodeURIComponent(f)+'/'+encodeURIComponent(q),score:20});
 result.sort((a,b)=>b.score-a.score);content.innerHTML=crumbs('Глобальный поиск')+head('Результаты: «'+q+'»',`Найдено ${result.length}. Поиск включает полные досье, утверждения, события, источники, каталог и тексты всех документов.`)+`<div class="callout">Однофамильцы и похожие названия остаются отдельными объектами. Совпадение в результатах поиска не устанавливает отношения между ними.</div><div class="list">${result.map(r=>`<article class="list-item"><div class="list-top">${neutral(r.kind)}</div><h3><a href="${esc(r.href)}">${highlightText(r.title,q)}</a></h3><p>${highlightText(snippet(r.text,q),q)}</p></article>`).join('')||'<div class="empty">Ничего не найдено. Попробуйте прежнюю фамилию, ИНН, номер регистрации или более короткий запрос.</div>'}</div>`;
}
function notFound(){content.innerHTML=crumbs('Не найдено')+head('Такой записи в корпусе нет','Проверьте ссылку или найдите объект через поиск.')+'<a class="button" href="#home">К результатам →</a>';}
function router(){
 const dialog=$('#evidence-dialog');if(dialog.open)dialog.close();
 const parts=location.hash.slice(1).split('/').map(s=>{try{return decodeURIComponent(s);}catch{return s;}}),[page='home',id]=parts;
 document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===page||((page==='entity')&&a.dataset.nav==='entities')||((page==='finding'||page==='topic')&&a.dataset.nav==='home')||((page==='source')&&a.dataset.nav==='sources')||((page==='lead')&&a.dataset.nav==='leads');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#sidebar').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false');
 switch(page||'home'){
  case 'home':home();break;case 'entities':directory();break;case 'entity':entityPage(id);break;case 'finding':finding(id);break;case 'topic':topicPage(id);break;case 'explore':explore(id);break;case 'timeline':timelinePage();break;case 'finance':finance();break;case 'documents':documents();break;case 'catalogue':catalogue();break;case 'catalogue-search':state.catalogueQuery=id||'';catalogue();break;case 'sources':sourcesPage();break;case 'source':sourcePage(id);break;case 'leads':leadsPage();break;case 'lead':leadsPage(id);break;case 'archive':archive(id);break;case 'archive-search':archive(id,parts[2]||'');break;case 'method':method();break;case 'search':searchPage(id||'');break;default:notFound();
 }
 document.title=($('#content h1')?.textContent||'EIA')+' · Открытое досье';
 if(page!=='archive-search')window.scrollTo(0,0);
}
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-source],[data-edge],[data-entity],[data-chain],[data-action],[data-image-load],[data-image-enlarge],[data-alternative]');if(!el)return;
 if(el.dataset.alternative!==undefined){const p=state.alternatives[Number(el.dataset.alternative)];state.path={...p,title:shortName(p.nodes[0])+' → '+shortName(p.nodes.at(-1)),body:'Альтернативная последовательность отдельных отношений.'};state.step=99;explore();return;}
 if(el.dataset.source){sourceDialog(el.dataset.source);return;}if(el.dataset.edge){edgeDialog(el.dataset.edge);return;}if(el.dataset.entity){location.hash='entity/'+el.dataset.entity;return;}
 if(el.dataset.chain){state.chain=el.dataset.chain;state.step=1;state.path=null;if(location.hash==='#explore/'+state.chain)explore(state.chain);else location.hash='explore/'+state.chain;return;}
 if(el.dataset.imageLoad){
  const frame=el.closest('.image-frame'),url=el.dataset.imageLoad,label=el.dataset.imageCaption;frame.classList.add('loaded');frame.innerHTML='';const img=new Image();img.alt=label;img.referrerPolicy='no-referrer';img.loading='lazy';img.dataset.imageEnlarge=url;img.dataset.imageCaption=label;
  img.onerror=()=>{frame.classList.remove('loaded');frame.innerHTML='<p class="notice">Оригинал недоступен или нет интернета. Текст исследования доступен полностью.</p>';};frame.appendChild(img);img.src=url.replace('&w=3840','&w=640');return;
 }
 if(el.dataset.imageEnlarge){showDialog(el.dataset.imageCaption,`<img src="${safeURL(el.dataset.imageEnlarge.replace('&w=3840','&w=1200'))}" alt="${esc(el.dataset.imageCaption)}" referrerpolicy="no-referrer"><p class="notice">Оригинал опубликован EIA. Лицензия на самостоятельную перепубликацию не установлена.</p><a class="button" href="${safeURL(el.dataset.imageEnlarge)}" target="_blank" rel="noopener noreferrer">Открыть оригинал ↗</a>`);return;}
 switch(el.dataset.action){
  case 'close-dialog':$('#evidence-dialog').close();break;
  case 'step-back':state.step=Math.max(1,state.step-1);explore();break;
  case 'step-next':state.step++;explore();break;
  case 'reset-graph':state.graphGrade=state.graphPeriod=state.graphKind=state.graphCountry=state.graphNodeKind='' ;state.path=null;state.chain=recommendations[0].id;state.step=99;explore();break;
  case 'find-path':{
   const a=$('#path-from').value,b=$('#path-to').value,p=getPath(a,b,allowedEdges());if(!p){$('#path-status').innerHTML='<div class="callout">В собранных данных по выбранным фильтрам путь не установлен. Это не доказательство отсутствия связи вне корпуса.</div>';return;}
   state.alternatives=alternativePaths(a,b,allowedEdges());state.path={...p,title:shortName(a)+' → '+shortName(b),body:'Кратчайший путь по отдельным отношениям. Достоверность ограничена самым слабым звеном.'};state.step=99;explore();$('#active-chain').scrollIntoView({behavior:'smooth',block:'start'});break;
  }
  case 'source-prev':state.sourcePage--;filterSources();$('#sources-count').scrollIntoView({block:'start'});break;
  case 'source-next':state.sourcePage++;filterSources();$('#sources-count').scrollIntoView({block:'start'});break;
 }
});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.target.matches('input,textarea,select')){e.preventDefault();$('#global-search').focus();}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-entity],[data-edge],[data-chain]')){e.preventDefault();e.target.click();}});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();const q=$('#global-search').value.trim();if(q)location.hash='search/'+encodeURIComponent(q);});
$('.menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open));});
$('#evidence-dialog').addEventListener('click',e=>{if(e.target===$('#evidence-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('input',e=>{switch(e.target.id){case 'entity-query':state.entityQuery=e.target.value;filterEntities();break;case 'source-query':state.sourceQuery=e.target.value;state.sourcePage=0;filterSources();break;case 'catalogue-query':state.catalogueQuery=e.target.value;filterCatalogue();break;}});
document.addEventListener('change',e=>{switch(e.target.id){case 'entity-kind':state.entityKind=e.target.value;filterEntities();break;case 'entity-country':state.entityCountry=e.target.value;filterEntities();break;case 'source-filter':state.sourceFilter=e.target.value;state.sourcePage=0;filterSources();break;case 'timeline-year':filterTimeline(e.target.value);break;case 'graph-grade':state.graphGrade=e.target.value;state.path=null;explore();break;case 'graph-period':state.graphPeriod=e.target.value;state.path=null;explore();break;case 'graph-kind':state.graphKind=e.target.value;state.path=null;explore();break;case 'graph-country':state.graphCountry=e.target.value;state.path=null;explore();break;case 'graph-node-kind':state.graphNodeKind=e.target.value;state.path=null;explore();break;}});
window.addEventListener('hashchange',router);
// Exposed read-only helpers make browser validation exercise the same live application.
window.EIA_APP=Object.freeze({getPath,alternativePaths,recommendations,graphSVG,route:router});
router();
})();
